/*
 * The firmware images compiled into the binary, generated by
 * tools/gpmd85/embed-roms.py: GPMD85Emulator's rom/ set (the monitors of
 * every model and the stock ROM modules) and the FujiNet CONFIG loader.
 *
 * paths.c materialises this table into the user's ROM directory on first
 * start; an entry is skipped when a file of that name is already there, so
 * a user's own copy always wins over the compiled-in one. See COMPLIANCE.md.
 *
 * Copyright (C) 2026 FujiNet Go contributors
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

#ifndef PMD85_ROMS_EMBEDDED_H
#define PMD85_ROMS_EMBEDDED_H

#include <stddef.h>

typedef struct {
    const char *name;            /* exact filename, e.g. "monit2A.rom" */
    const unsigned char *data;
    size_t size;
} pmd85_embedded_rom;

extern const pmd85_embedded_rom pmd85_embedded_roms[];
extern const int pmd85_embedded_rom_count;

#endif /* PMD85_ROMS_EMBEDDED_H */
